function Power(x: real; n: integer): real;
begin
  case n of
  0: Result := 1;
  1: Result := x;
  2: Result := x*x;
  3: Result := x*x*x;
  4: Result := x*x*x*x;
  5: Result := x*x*x*x*x;
  6: Result := x*x*x*x*x*x;
  else
  if n<0 then
    Result := 1/Power(x,-n)
  else  
    begin
      var z := x;
      var r := 1.0;
      while n > 0 do
      begin
        if n and 1 = 1 then
          r := r * z;
        z := z * z;
        n := n shr 1;
      end;
      Result := r;
    end;
  end;
end;

