procedure InsertInShortString(subs: string; var s: string; index, n: integer);
begin
  if index < 1 then 
    index := 1;
  if index > n then
    exit;
  try
    s := s.Insert(index - 1, subs);
    if s.Length > n then s := s.Substring(0, n);
  except
    s := s.Insert(s.Length, subs);
    if s.Length > n then s := s.Substring(0, n);
  end;
end;

