  var fromv := from - 1;
  var tov := &to - 1;
  var count := CheckAndCorrectFromToAndCalcCountForSystemSlice(situation, Self.Length, fromv, tov, step);

  if step = 1 then
    Result := Self.Substring(fromv,count) 
  else Result := CreateSliceFromStringInternal(Self, fromv + 1, step, count)
