function FromOneDimN<T>(r: array of T; l: array of SliceType): System.Array;
begin
  var rank := l.Count(x -> x.oneelem = False);
  case rank of
    1: Result := r;
    2: Result := FromOneDim2(r,l);
    3: Result := FromOneDim3(r,l);
    4: Result := FromOneDim4(r,l);
  end;  
end;

